import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def euler_phi(n, factors):
    result = n
    for p in factors:
        result -= result // p
    return result

N = 2013
factors = prime_factorization(N)
phi = euler_phi(N, factors.keys())

print(f"Factorization of {N}: {factors}")
print(f"phi({N}) = {phi}")
